import{z as A,x as s,o as B,c as p,q as r,j as t,D as i,d as e,s as o,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"限制进入定价","description":"","frontmatter":{"title":"限制进入定价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/limit-pricing.md","filePath":"econ/limit-pricing.md","lastUpdated":1791063341000}'),d={name:"econ/limit-pricing.md"};function m(F,E,C,_,c,D){const n=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=r('<h1 id="限制进入定价" tabindex="-1">限制进入定价 <a class="header-anchor" href="#限制进入定价" aria-label="Permalink to &quot;限制进入定价&quot;">​</a></h1><div class="epigraph"><p>在位者把产量或价格钉在使进入无利的位置上；若成本是私有信息，限价还可能是信号，而不只是多产本身。</p><footer>—— 据 Bain, Barriers to New Competition, 1956；Milgrom and Roberts, Limit Pricing and Entry under Incomplete Information, Econometrica, 1982 整理</footer></div><p>定位：<a href="/econ/stackelberg">上一课</a>。产量领导在<strong>已在场</strong>的跟随者反应曲线上选切点。本课不重讲 \\(R(q_L)\\) 的切。缺口是第三家还没进来：在位者面对的是潜在进入者的进入决策，不是跟随者的产量。Bain 的结构主义用低价/高产把剩余需求压到进入后利润为负；芝加哥式批评说进入一旦发生限价就无用。Milgrom–Roberts 用私有成本把限价救成信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进入者支付沉没 \\(F\\)，进入后与在位者玩古诺或伯川德，得到 \\(\\pi_E\\)。进入当且仅当 \\(\\pi_E\\ge F\\)。在位者若能在进入<strong>前</strong>改变进入者对 \\(\\pi_E\\) 的信念或改变进入后的竞争环境，就可以把进入挡在门外。缺口不是再写一次先动优势，而是：<strong>事前的价格/产量如何进入 \\(\\pi_E\\) 的计算。</strong></p><p><span class="marginnote">数字实例：进入要沉没 \\(F=500\\) 万，进入后预计赚 \\(\\pi_E=300\\) 万，于是不进。若在位者把价格再压低、\\(\\pi_E\\) 掉到 200 万，离 \\(F\\) 更远。限价的全部目标，就是把 \\(\\pi_E\\lt F\\) 这个不等式钉死。</span></p><p>Bain–Sylos 传统：在位者承诺进入后仍维持高产（Sylos 公设），进入者面对剩余需求 \\(D(p)-q_I\\)，限价是使 \\(\\pi_E=F\\) 的那个 \\(p_L\\)。承诺若不可信——进入发生后在位者想收缩到双寡最优——限价只是廉价交谈。上一课刚强调承诺必须沉没；这里同一把刀：没有不可逆产能，Bain 的限价不是子博弈完美。</p><h3 id="信号限价不是结构限价" tabindex="-1">信号限价不是结构限价 <a class="header-anchor" href="#信号限价不是结构限价" aria-label="Permalink to &quot;信号限价不是结构限价&quot;">​</a></h3><p>Milgrom–Roberts：在位成本 \\(c_L\\in\\{c_H,c_L\\}\\) 私有，进入者进入后才（或仍不）完全知情。低成本类型在进入前选一个高成本学不起的低价，分离均衡里进入者推断 \\(c_L\\) 从而留下；高成本类型只好要较高的垄断价并被进入。限价的成本是进入前产量偏离垄断点；收益是改变信念。完全信息下这套信号无用，回到「只有沉没产能才能阻挠」。</p><p><span class="marginnote">直觉类比：分离信号像二手车商「愿意给十年质保」——只有真信自家车没问题（低成本）的卖家给得起。质保本身亏钱，但正因为高成本卖家学不起，它才成为可信信号。</span></p><p><span class="marginnote">Bain 1956 的进入壁垒是结构清单：规模经济、绝对成本优势、产品差异。限价是在位行为，不是壁垒本身。不要把有效规模相对于市场的大小直接叫成限价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>完全信息、可观察产能：在位者先选 \\(K\\)，进入者看见 \\(K\\) 再决定进不进；若进，价格阶段或产量阶段在既定产能上打。这是斯塔克尔伯格对「进入者产量为零」这一角点的延伸：选 \\(K\\) 使进入后 \\(\\pi_E\\lt F\\)，在位者比较「容忍进入的双寡利润」与「为阻挠而过量安装的利润」，不一定总阻挠。</p><p>不完全信息：进入前价格是信号。分离、混同都可能。混同时高成本也被迫限价，社会福利可以更差。本课钉对照：结构路径靠承诺，信息路径靠信念，不要合成一个「低价」口头禅。</p><p>进入成本 \\(F\\) 越大，阻挠越便宜；市场需求越大，容忍进入往往更划算——不一定总限价。</p>',15)),(B(),t(l,null,{default:i(()=>[o(n,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E6%96%AF%E5%A1%94%E5%85%8B%E5%B0%94%E4%BC%AF%E6%A0%BC%EF%BC%9A%E5%AF%B9%E5%9C%A8%E5%9C%BA%E8%B7%9F%E9%9A%8F%E8%80%85%22%5D%20--%3E%20POT%5B%22%E6%BD%9C%E5%9C%A8%E8%BF%9B%E5%85%A5%EF%BC%9A%CF%80_E%20%E5%AF%B9%20F%22%5D%0A%20%20POT%20--%3E%20BAIN%5B%22%E7%BB%93%E6%9E%84%EF%BC%9A%E6%89%BF%E8%AF%BA%E9%AB%98%E4%BA%A7%E5%8E%8B%E5%89%A9%E4%BD%99%E9%9C%80%E6%B1%82%22%5D%0A%20%20POT%20--%3E%20MR%5B%22%E4%BF%A1%E6%81%AF%EF%BC%9A%E4%BD%8E%E4%BB%B7%E4%BF%A1%E5%8F%B7%E4%BD%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20BAIN%20--%3E%20CRED%5B%22%E6%97%A0%E6%B2%89%E6%B2%A1%E5%88%99%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20MR%20--%3E%20SEP%5B%22%E5%88%86%E7%A6%BB%EF%BC%9A%E5%8F%AA%E6%9C%89%E4%BD%8E%E6%88%90%E6%9C%AC%E9%99%90%E4%BB%B7%22%5D%0A"})]),fallback:i(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"不要把限价写成限价簿上的保护买/卖；那是微观结构的指令类型，这里是产品市场的进入前价格。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("结构阻挠的机制是剩余需求：在位者把 \\(q_I\\) 沉没得足够大，进入者即使打满自己的产能也赚不回 \\(F\\)。与"),a("a",{href:"/econ/long-run-entry"},"长期进入"),e("对照：完全竞争里人人价格接受，没有谁能单独把 \\(n\\) 挡在门外；这里 \\(n=1\\) 对 \\(n=2\\) 的跳跃足够大，在位者内部化进入对自己利润的损害。")],-1)),E[6]||(E[6]=a("p",null,"信号机制是直觉准则一类精炼：高成本模仿低价的损失更大（同样的低价对高 MC 更亏），于是低价成为低成本的昂贵信号。进入者要的不是「看见低价」本身，而是推断进入后的竞争会更狠。",-1)),(B(),t(l,null,{default:i(()=>[o(n,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20OWN%5B%22%E5%9C%A8%E4%BD%8D%E8%80%85%E7%9F%A5%E9%81%93%E8%87%AA%E5%B7%B1%E7%9A%84%E7%9C%9F%E5%AE%9E%E6%88%90%E6%9C%AC%22%5D%20--%3E%20LC%5B%22%E4%BD%8E%E6%88%90%E6%9C%AC%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20OWN%20--%3E%20HC%5B%22%E9%AB%98%E6%88%90%E6%9C%AC%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20LC%20--%3E%20PL%5B%22%E5%AE%9A%E4%BB%B7%20p_L%EF%BC%9A%E9%AB%98%E6%88%90%E6%9C%AC%E5%AD%A6%E4%B8%8D%E8%B5%B7%E7%9A%84%E4%BD%8E%E4%BB%B7%22%5D%0A%20%20HC%20--%3E%20PH%5B%22%E5%8F%AA%E8%83%BD%E5%AE%9A%E8%BE%83%E9%AB%98%E7%9A%84%E5%9E%84%E6%96%AD%E4%BB%B7%22%5D%0A%20%20PL%20--%3E%20INF%5B%22%E8%BF%9B%E5%85%A5%E8%80%85%E6%8E%A8%E6%96%AD%EF%BC%9A%E5%AF%B9%E6%89%8B%E6%88%90%E6%9C%AC%E5%BE%88%E4%BD%8E%22%5D%0A%20%20PH%20--%3E%20INF2%5B%22%E6%8E%A8%E6%96%AD%EF%BC%9A%E5%AF%B9%E6%89%8B%E6%88%90%E6%9C%AC%E9%AB%98%22%5D%0A%20%20INF%20--%3E%20STAY%5B%22%E6%94%BE%E5%BC%83%E8%BF%9B%E5%85%A5%22%5D%0A%20%20INF2%20--%3E%20ENTER%5B%22%E8%BF%9B%E5%85%A5%E5%8F%91%E7%94%9F%22%5D%0A"})]),fallback:i(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<p>与卡特尔对照：合谋是在位者之间的重复惩罚；限价是在位者对尚未进来的人。两者都可以表现为「低价」，但一阶条件不同——一个压住偏离，一个改进入者的 \\(\\pi_E\\) 或信念。把限价读成合谋的触发策略，会把潜在竞争与实际竞争焊死。</p><p><span class="marginnote">常见误区：看见在位者卖得便宜就以为消费者稳赚。若是信号限价，低价只是压住进入的诱饵；一旦进入威胁解除，价格常回到垄断水平——判断福利要盯着「进入是否真的被挡住」。</span></p><p><span class="marginnote">Milgrom–Roberts 1982 是不完全信息的进入阻挠，不是把 Bain 的公设博弈论化。引用时分开：一个靠产能承诺，一个靠信念。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多期声誉、掠夺性定价（把进入者打出去）与限价（不让进来）时序不同，本课不把二者写成同一个一阶条件。规制价格上限可以碰巧看起来像限价。差异产品、多市场交叉补贴会改信号成本。进入者若也有私有成本，信号变成双向，分离更脆。</p><p>芝加哥式「限价不可信」只打中无承诺的 Bain 路径，打不中分离均衡里的信号。</p><p>后课<a href="/econ/hotelling">霍特林</a>把产品差异做成位置；限价若靠品牌与广告，那是差异而不只是 \\(p\\)。后课默认：完全信息限价需要沉没承诺；私有成本时限价可以是信号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限价对付潜在进入，不是斯塔克尔伯格对在场跟随者的切点。</li><li>Bain 路径靠不可逆产量/产能；无承诺则不可信。</li><li>Milgrom–Roberts 路径靠分离信号；完全信息下用不上。</li><li>下一课用线性城市把产品差异做成位置，不再挡进入。</li><li>出处：Bain, 1956；Milgrom and Roberts, <em>Econometrica</em>, 1982。</li></ul>',9))])}const u=A(d,[["render",m]]);export{h as __pageData,u as default};
